        /\ L5.u64_at RSEGS M' 2147469248 0
        /\ L5.u64_at RSEGS M' 2147469240 0
        /\ L5.u64_at RSEGS M' 2147469232 0
        /\ L5.u64_at RSEGS M' 2147469224 0
        /\ L5.u32_at RSEGS M' 2147470036 0
        /\ L5.u32_at RSEGS M' 2147470032 0
        /\ L5.u32_at RSEGS M' 2147470028 0
        /\ L5.u32_at RSEGS M' 2147470024 0
        /\ L5.u32_at RSEGS M' 2147469220 0
        /\ L5.u32_at RSEGS M' 2147469216 0
        /\ L5.u32_at RSEGS M' 2147469212 0
        /\ L5.u32_at RSEGS M' 2147469208 0
        /\ L5.u32_at RSEGS M' 2147470044 0
        /\ L5.u32_at RSEGS M' 2147470040 0
        /\ L5.u32_at RSEGS M' 2147469204 0
        /\ L5.u32_at RSEGS M' 2147469200 0
        /\ L5.u32_at RSEGS M' 2147470048 0
        /\ L5.u32_at RSEGS M' 2147469196 0
        /\ L5.u8_at RSEGS M' 2147469194 0
        /\ L5.u8_at RSEGS M' 2147469193 0
        /\ L5.u8_at RSEGS M' 2147469195 0
        /\ L5.u8_at RSEGS M' 2147469192 0
        /\ L5.u8_at RSEGS M' 2147469190 0
        /\ L5.u8_at RSEGS M' 2147469189 0
        /\ L5.u8_at RSEGS M' 2147469191 0
        /\ L5.u8_at RSEGS M' 2147469188 0
        /\ L5.u8_at RSEGS M' 2147469172 0
        /\ L5.u8_at RSEGS M' 2147469171 0
        /\ L5.u8_at RSEGS M' 2147469174 0
        /\ L5.u8_at RSEGS M' 2147469173 0
        /\ L5.u8_at RSEGS M' 2147469170 0
        /\ L5.u8_at RSEGS M' 2147469169 0
        /\ L5.u8_at RSEGS M' 2147469175 0
        /\ L5.u8_at RSEGS M' 2147469168 0
        /\ L5.u8_at RSEGS M' 2147469166 0
        /\ L5.u8_at RSEGS M' 2147469165 0
        /\ L5.u8_at RSEGS M' 2147469167 0
        /\ L5.u8_at RSEGS M' 2147469164 0
        /\ L5.u32_at RSEGS M' 2147469156 0
        /\ L5.u32_at RSEGS M' 2147469152 0
        /\ L5.u32_at RSEGS M' 2147469160 0
        /\ L5.u8_at RSEGS M' 2147469150 0
        /\ L5.u8_at RSEGS M' 2147469149 0
        /\ L5.u8_at RSEGS M' 2147469151 0
        /\ L5.u8_at RSEGS M' 2147469148 0
        /\ L5.u32_at RSEGS M' 2147469136 0
        /\ L5.u32_at RSEGS M' 2147469132 0
        /\ L5.u32_at RSEGS M' 2147469140 0
        /\ L5.u8_at RSEGS M' 2147469130 0
        /\ L5.u8_at RSEGS M' 2147469129 0
        /\ L5.u8_at RSEGS M' 2147469131 0
        /\ L5.u8_at RSEGS M' 2147469128 0
        /\ L5.u64_at RSEGS M' ((V 2%nat) - 144) (bv_unsigned (getr R (reg 22)))
        /\ L5.u8_at RSEGS M' 1426448 1
        /\ L5.u8_at RSEGS M' 7027536 1
        /\ L5.u64_at RSEGS M' 7027552 0
        /\ L5.u32_at RSEGS M' 7027544 32
        /\ L5.u32_at RSEGS M' 7028080 (V 44%nat)
        /\ L5.u64_at RSEGS M' ((V 2%nat) - 16) (bv_unsigned (getr R (reg 8)))
        /\ L5.u64_at RSEGS M' ((V 2%nat) - 8) 1275140).
Proof.
  assert (Hgap : forall x lo n : Z, ~ (lo <= x < lo + n) -> x < lo \/ lo + n <= x)
    by (intros x lo n Hnot_in; lia).
  intros Hsp_rng Hv40_rng Hv44_rng Hra_in Hsp_in Htp_in Hsp_win.
  assert (Hsp_lo : 0 <= V 2%nat + -320) by lia.
  assert (Hsp_hi : V 2%nat + -320 + 320 <= 2 ^ 64) by lia.
  intros Hsp_align Hsp_wr Hsp_def Himg.
  intros.
  (* Entry environment of the segment: registers read from R, variables 32.. read from V. *)
  pose (Ein := BG.E_R R (fun j => Z_to_bv 64 (V j)) (fun _ => @nil byte)).
  assert (Hsp_ev : bv_unsigned (ev Ein 2) = V 2%nat).
  { change (bv_unsigned (getr R (Z_to_bv 5 (Z.of_nat 2))) = V 2%nat).
    rewrite Hsp_in. apply BG.unsigned_lit. exact Hsp_rng. }
  assert (Hv40_ev : bv_unsigned (ev Ein 40) = V 40%nat).
  { change (bv_unsigned (Z_to_bv 64 (V 40%nat)) = V 40%nat). apply BG.unsigned_lit. exact Hv40_rng. }
  assert (Hv44_ev : bv_unsigned (ev Ein 44) = V 44%nat).
  { change (bv_unsigned (Z_to_bv 64 (V 44%nat)) = V 44%nat). apply BG.unsigned_lit. exact Hv44_rng. }
  assert (Hregs_in : regs_ok Ein PdpX4_pre.regs0 R).
  { apply (BG.regs_ok_slots R (fun j => Z_to_bv 64 (V j)) (fun _ => @nil byte)); [reflexivity |].
    unfold PdpX4_pre.regs0. cbn [BG.slots_ok].
    repeat (apply conj; [first [left; reflexivity | exact (getr_zero R) | exact Hra_in | exact Htp_in] |]).
    exact I. }
  (* Each entry of the segment's knowledge list is one premise, read back in kentry form. *)
  assert (Hknow : know_ok RSEGS Ein M PdpX4_pre.kn0).
  { unfold know_ok, PdpX4_pre.kn0.
    repeat (apply Forall_cons; [
      lazymatch goal with
      | |- kentry_ok _ _ _ (KRange (EVar ?j) ?lo ?hi) =>
          apply (L5K.kentry_KRange RSEGS Ein M (EVar j) lo hi (V j));
          [first [exact Hsp_ev | exact Hv44_ev] | assumption]
      | |- kentry_ok _ _ _ (KAlign (EVar 2) ?m) =>
          apply (L5K.kentry_KAlign RSEGS Ein M (EVar 2) m (V 2%nat));
          [exact Hsp_ev | apply Z.ltb_lt; reflexivity | exact Hsp_align]
      | |- kentry_ok _ _ _ (KWr {| a_base := EVar 2; a_off := ?o |} (ELit ?n)) =>
          apply (L5K.kentry_KWr RSEGS Ein M (EVar 2) o (ELit n) (V 2%nat) n);
          [exact Hsp_ev | reflexivity | exact Hsp_lo | apply Z.ltb_lt; reflexivity | exact Hsp_hi | exact Hsp_wr]
      | |- kentry_ok _ _ _ (KUnk {| a_base := EVar 2; a_off := ?o |} (ELit ?n)) =>
          apply (L5K.kentry_KUnk RSEGS Ein M (EVar 2) o (ELit n) (V 2%nat) n);
          [exact Hsp_ev | reflexivity | exact Hsp_lo | apply Z.ltb_lt; reflexivity | exact Hsp_hi | exact Hsp_def]
      | |- kentry_ok _ _ _ (KImg ?lo ?hi) =>
          apply (L5K.kentry_KImg RSEGS Ein M lo hi); [apply Z.leb_le; reflexivity | apply Z.leb_le; reflexivity | exact Himg]
      | |- kentry_ok _ _ _ (KWr {| a_base := ELit 0; a_off := ?o |} (ELit ?n)) =>
          apply (L5K.kentry_KWr RSEGS Ein M (ELit 0) o (ELit n) 0 n);
          [ reflexivity | reflexivity | apply Z.leb_le; reflexivity | apply Z.ltb_lt; reflexivity
          | apply Z.leb_le; reflexivity
          | match goal with Hfact : L5.writable _ _ o n |- _ => exact Hfact end ]
      | |- kentry_ok _ _ _ (KWord {| a_base := ELit 0; a_off := ?o |} ?w ?e) =>
          let v := lazymatch e with ELit ?c => c | EVar ?j => constr:(V j) end in
          lazymatch w with
          | 8%nat =>
              apply (L5K.kentry_KWord8 RSEGS Ein M (ELit 0) o e 0 v);
              [ reflexivity | first [reflexivity | exact Hv40_ev | exact Hv44_ev]
              | apply Z.leb_le; reflexivity | apply Z.leb_le; reflexivity
              | match goal with Hfact : L5.u64_at _ _ o v |- _ => exact Hfact end ]
          | 4%nat =>
              apply (L5K.kentry_KWord4 RSEGS Ein M (ELit 0) o e 0 v);
              [ reflexivity | first [reflexivity | exact Hv40_ev | exact Hv44_ev]
              | apply Z.leb_le; reflexivity | apply Z.leb_le; reflexivity
              | match goal with Hfact : L5.u32_at _ _ o v |- _ => exact Hfact end ]
          | 1%nat =>
              apply (L5K.kentry_KWord1 RSEGS Ein M (ELit 0) o e 0 v);
              [ reflexivity | first [reflexivity | exact Hv40_ev | exact Hv44_ev]
              | apply Z.leb_le; reflexivity | apply Z.leb_le; reflexivity
              | split; [apply Z.leb_le | apply Z.ltb_lt]; reflexivity
              | match goal with Hfact : L5.u8_at _ _ o v |- _ => exact Hfact end ]
          end
      end | ]).
    apply Forall_nil. }
  clear - Hgap Hsp_rng Hsp_in Hsp_ev Hv40_ev Hv44_ev Hregs_in Hknow.
  destruct (PdpX4_pre.seg_sound_ax fx Ein R M Hregs_in Hknow (Forall_nil _))
    as (fx' & Eout & R' & M' & ps_idx & ps & Hps_nth & Hagree & Hsteps & Hregs_out & Hzero_out & Hregions & Hframe & Hcells & Hgrow).
  change PdpX4_pre.PSS with [PdpX4_pre.ps0] in Hps_nth.
  apply L5K.nth_error_single in Hps_nth. subst ps.
  clear Hzero_out Hregions ps_idx.
  (* Variables below NX0 = 56 keep their entry value. *)
  assert (Hev_keep : forall j, (j < 56)%nat -> ev Eout j = ev Ein j).
  { intros j Hj_lt. symmetry. exact (proj1 Hagree j Hj_lt). }
  assert (Hsp_eout : bv_unsigned (ev Eout 2) = V 2%nat).
  { rewrite Hev_keep by (apply Nat.ltb_lt; reflexivity). exact Hsp_ev. }
  assert (Hsp_eout_word : ev Eout 2 = Z_to_bv 64 (V 2%nat)).
  { rewrite Hev_keep by (apply Nat.ltb_lt; reflexivity). exact Hsp_in. }
  assert (Hv40_eout : bv_unsigned (ev Eout 40) = V 40%nat).
  { rewrite Hev_keep by (apply Nat.ltb_lt; reflexivity). exact Hv40_ev. }
  assert (Hv44_eout : bv_unsigned (ev Eout 44) = V 44%nat).
  { rewrite Hev_keep by (apply Nat.ltb_lt; reflexivity). exact Hv44_ev. }
  exists fx', R', M'.
  (* Frame over words: an address outside every footprint region keeps its byte. *)
  match goal with |- _ /\ (?Fwords /\ _) => assert (Hframe_w : Fwords) end.
  { intros a. intros. apply Hframe. unfold SGP.outside, PdpX4_pre.F0.
    repeat (apply Forall_cons; [
      hnf; apply Hgap;
      lazymatch goal with
      | |- ~ (estart _ {| a_base := EVar 2; a_off := _ |} <= _ < _) =>
          unfold estart, elenZ; cbn [a_base a_off edenot]; rewrite Hsp_eout; assumption
      | |- ~ (estart ?Ex ?sa <= _ < _ + elenZ ?Ex ?ne) =>
          let lo := eval vm_compute in (estart Ex sa) in
          let len := eval vm_compute in (elenZ Ex ne) in
          change (estart Ex sa) with lo; change (elenZ Ex ne) with len; assumption
      end | ]).
    apply Forall_nil. }
  split; [exact Hgrow |].
  split; [exact Hframe_w |].
  split.
  { intros i Hi_rng. pose proof (Hframe_w (Z_to_bv 64 i)) as Hframe_i.
    rewrite (BG.unsigned_lit i Hi_rng) in Hframe_i. exact Hframe_i. }
  split; [exact Hsteps |].
  split.
  { intros x Hx_kept.
    exact (BG.kept_regs Ein Eout R R' PdpX4_pre.regs0 PdpX4_pre.regs_out0 56 KS_dpX4_pre
             KS_dpX4_pre_ok Hregs_in Hagree Hregs_out x Hx_kept). }
  (* Registers the segment writes. *)
  repeat lazymatch goal with
  | |- getr R' (Z_to_bv 5 (Z.of_nat ?k)) = _ /\ _ =>
      split; [
        rewrite (BG.out_reg PdpX4_pre.regs_out0 Eout R' k Hregs_out ltac:(split; apply Nat.ltb_lt; reflexivity));
        unfold PdpX4_pre.regs_out0; cbn [nth edenot];
        first [reflexivity | rewrite Hsp_eout_word, BG.alu_add_lit; reflexivity]
      | ]
  end.
  (* Exit cells: the post-spec lists them in the order the conclusion states them. *)
  assert (Hcell_list : Forall (kentry_ok RSEGS Eout M') PdpX4_pre.cells0)
    by (apply Forall_forall; exact Hcells).
  unfold PdpX4_pre.cells0 in Hcell_list.
  clear Hcells Hframe Hframe_w Hsteps Hgrow Hknow.
  let close_cell Hk :=
    let base_tac := first [exact Hsp_eout | reflexivity] in
    let value_tac :=
      cbn [edenot];
      first [ reflexivity | exact Hv40_eout | exact Hv44_eout
            | rewrite Hev_keep by (apply Nat.ltb_lt; reflexivity); reflexivity ] in
    lazymatch goal with
    | |- L5.u64_at _ _ _ _ => eapply (u64_of_KWord8a Eout M' _ _ _ _ _ _ Hk); [base_tac | value_tac | reflexivity]
    | |- L5.u32_at _ _ _ _ => eapply (u32_of_KWord4a Eout M' _ _ _ _ _ _ Hk); [base_tac | value_tac | reflexivity]
    | |- L5.u8_at _ _ _ _ =>
        eapply (u8_of_KWord1a Eout M' _ _ _ _ _ _ Hk);
        [base_tac | value_tac | split; [apply Z.leb_le | apply Z.ltb_lt]; reflexivity | reflexivity]
    end in
  repeat (
    lazymatch goal with Hcl : Forall _ (_ :: _) |- _ =>
      let Hcell := fresh "Hcell" in
      pose proof (Forall_inv Hcl) as Hcell; apply Forall_inv_tail in Hcl;
      first [ split; [close_cell Hcell |] | close_cell Hcell ];
      clear Hcell
    end).
Qed.
